def specs_for(plugin_name: str) -> tuple:
    """The censused `TableSpec`s for one plugin, or an empty tuple."""
    return tuple(
        TableSpec(subject, filename, _K[kind], "plaintext", label_key=label)
        for subject, filename, kind, label, _note, _lines
        in CENSUSED.get(plugin_name, ()))


def note_for(plugin_name: str, subject: str) -> str:
    """What was measured about one censused table's label."""
    for s, _f, _k, _l, note, _n in CENSUSED.get(plugin_name, ()):
        if s == subject:
            return note
    return ""


def extend(curated: tuple, plugin_name: str) -> tuple:
    """Curated specs first, then the censused ones that do not collide.

    **A hand-written spec always wins**, on SUBJECT and on FILENAME. The
    curated one was authored by someone who knew what the table means and
    which of its columns matter; this file knows only what shape the file is
    in. Losing a curated `label_key` or a curated `refusal` to a generated
    entry would be a silent downgrade of the better answer.
    """
    curated = tuple(curated)
    taken = {s.subject for s in curated}
    files = {s.filename.lower() for s in curated}
    return curated + tuple(
        s for s in specs_for(plugin_name)
        if s.subject not in taken and s.filename.lower() not in files)
